// TrustInbox payload (see services/bot-service/internal/infra/n8n/client.go):
//   { workflowId, botId, serviceProviderId, conversationId, userId,
//     resumeCallbackUrl, inputData: <raw JSON from execute_workflow tool> }
//
// The bot's `execute_workflow` tool passes whatever the LLM puts in
// `input_data` straight through. For this sample we expect:
//   { "name": "Alice", "intent": "hello" }

const body = $input.first().json;
const input = body.inputData || {};
const name = input.name || 'there';
const intent = input.intent || 'hello';

let message;
switch (intent) {
  case 'hello':
    message = `Hello ${name}! 👋 Thanks for reaching out — how can I help?`;
    break;
  case 'order_status':
    message = `Hi ${name}, your order is being processed and will ship within 24h.`;
    break;
  case 'business_hours':
    message = `Our team is available Monday–Friday, 9am–6pm IST.`;
    break;
  default:
    message = `Hi ${name}, I received your request but don't recognise the intent "${intent}".`;
}

return [
  {
    json: {
      success: true,
      data: {
        message,
        handledBy: 'n8n-sample-greeting-workflow',
        intent,
        botId: body.botId,
        userId: body.userId,
        timestamp: new Date().toISOString()
      }
    }
  }
];
